        static void BuildRound5LayerSurface(TerrainData td,bool[,] holes,R5Construction recipe){
            var ground=new GameObject("Ground").transform;ground.SetParent(world,false);var weights=td.GetAlphamaps(0,0,512,512);var pixels=new Color32[512*512];var mask=new byte[512*512];for(int y=0;y<512;y++)for(int x=0;x<512;x++){pixels[y*512+x]=new Color32((byte)Mathf.RoundToInt(weights[y,x,0]*255),(byte)Mathf.RoundToInt(weights[y,x,1]*255),(byte)Mathf.RoundToInt(weights[y,x,2]*255),255);mask[y*512+x]=holes[y,x]?(byte)255:(byte)0;}
            var control=new Texture2D(512,512,TextureFormat.RGBA32,true,true){name="Original Terrain Layer weights",wrapMode=TextureWrapMode.Clamp,filterMode=FilterMode.Trilinear};control.SetPixels32(pixels);control.Apply();control=Save(control,"LayerWeights.asset");const int shoreResolution=4096;var shoreMask=new byte[shoreResolution*shoreResolution];for(int y=0;y<shoreResolution;y++)for(int x=0;x<shoreResolution;x++){float wx=r5GroundBounds.x+(x+.5f)*r5GroundBounds.z/shoreResolution,py=-r5GroundBounds.y-(y+.5f)*r5GroundBounds.w/shoreResolution;float d=wx<7||wx>33||py<35||py>54?1:R5ShoreDistance(wx,py,recipe);shoreMask[y*shoreResolution+x]=(byte)Mathf.RoundToInt(Mathf.Clamp01(.5f+d/.60f)*255);}var holeTexture=new Texture2D(shoreResolution,shoreResolution,TextureFormat.R8,false,true){name="Authored continuous curved shore distance",wrapMode=TextureWrapMode.Clamp,filterMode=FilterMode.Bilinear};holeTexture.LoadRawTextureData(shoreMask);holeTexture.Apply();holeTexture=Save(holeTexture,"LayerHoles.asset");
            var shader=Resources.Load<Shader>("Map25D/R5Ground");if(shader==null||ShaderUtil.ShaderHasError(shader))throw new Exception("R5 terrain-layer shader invalid");var mat=new Material(shader){name="R5 original Terrain Layers on original heightfield"};mat.SetTexture("_Soil",td.terrainLayers[0].diffuseTexture);mat.SetTexture("_Litter",td.terrainLayers[1].diffuseTexture);mat.SetTexture("_Mud",td.terrainLayers[2].diffuseTexture);mat.SetTexture("_Normal",Texture("r4_tex_mud_normal"));mat.SetTexture("_Control",control);mat.SetTexture("_Holes",holeTexture);mat.SetVector("_LayerScale",new Vector4(td.terrainLayers[0].tileSize.x,td.terrainLayers[1].tileSize.x,td.terrainLayers[2].tileSize.x,0));mat=Save(mat,"LayerSurface.mat");
