        }

        static float R5ShoreDistance(float wx,float py,R5Construction c){
            float basin=100;foreach(var b in c.swamp){float u=(wx-b.x)/b.z,v=(py-b.y)/b.w;basin=Mathf.Min(basin,(Mathf.Sqrt(u*u+v*v)-.86f)*Mathf.Min(b.z,b.w));}
            var points=c.shoreCurve;float bank=points[0].x;for(int i=0;i+1<points.Length;i++)if(py>=points[i].y){float t=Mathf.InverseLerp(points[i].y,points[i+1].y,py);float a=points[Mathf.Max(0,i-1)].x,b=points[i].x,d=points[i+1].x,e=points[Mathf.Min(points.Length-1,i+2)].x;bank=.5f*(2*b+(-a+d)*t+(2*a-5*b+4*d-e)*t*t+(-a+3*b-3*d+e)*t*t*t);}
            bank+=.18f*(Mathf.PerlinNoise(py*.70f,91.7f)*2-1)+.07f*(Mathf.PerlinNoise(py*1.80f,17.3f)*2-1)-.35f;
            var local=Quaternion.Euler(0,-c.bridgeYaw,0)*new Vector3(wx-c.bridgeX/100,0,-py+c.bridgeY/100);float deck=Mathf.Max(Mathf.Abs(local.x)-c.bridgeWidth*.28f,Mathf.Abs(local.z)-c.bridgeLength*.43f);
            return Mathf.Min(Mathf.Max(wx-bank,basin),Mathf.Max(deck,basin));
        }
