        static Mesh TimberBox(Vector3 size){
            var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();Vector3 h=size*.5f;
            Vector3[][] faces={new[]{new Vector3(-h.x,h.y,-h.z),new Vector3(-h.x,h.y,h.z),new Vector3(h.x,h.y,h.z),new Vector3(h.x,h.y,-h.z)},new[]{new Vector3(-h.x,-h.y,h.z),new Vector3(-h.x,-h.y,-h.z),new Vector3(h.x,-h.y,-h.z),new Vector3(h.x,-h.y,h.z)},new[]{new Vector3(-h.x,-h.y,-h.z),new Vector3(-h.x,h.y,-h.z),new Vector3(h.x,h.y,-h.z),new Vector3(h.x,-h.y,-h.z)},new[]{new Vector3(h.x,-h.y,h.z),new Vector3(h.x,h.y,h.z),new Vector3(-h.x,h.y,h.z),new Vector3(-h.x,-h.y,h.z)},new[]{new Vector3(-h.x,-h.y,h.z),new Vector3(-h.x,h.y,h.z),new Vector3(-h.x,h.y,-h.z),new Vector3(-h.x,-h.y,-h.z)},new[]{new Vector3(h.x,-h.y,-h.z),new Vector3(h.x,h.y,-h.z),new Vector3(h.x,h.y,h.z),new Vector3(h.x,-h.y,h.z)}};
            for(int f=0;f<6;f++){int i=v.Count;v.AddRange(faces[f]);float u=f<4?size.x:size.z,w=f<2?size.z:size.y;uv.AddRange(new[]{new Vector2(0,0),new Vector2(0,w*.65f),new Vector2(u*.65f,w*.65f),new Vector2(u*.65f,0)});tri.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});}var mesh=new Mesh{name="Metre-registered timber"};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateTangents();return mesh;
        }
