        static Texture2D BuildCoreWalkMask(){const int size=2048;var raw=new byte[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++)raw[y*size+x]=map.CanMove((x+.5f)*8000/size,(y+.5f)*8000/size,0)?(byte)255:(byte)0;var texture=new Texture2D(size,size,TextureFormat.R8,false,true){name="Unchanged Core walk image",filterMode=FilterMode.Point,wrapMode=TextureWrapMode.Clamp};texture.LoadRawTextureData(raw);texture.Apply();return Save(texture,"R3_CoreWalkMask.asset");}
        static void BuildProjectedWebCard(Map25DCard c,Shader shader,Transform cards,Transform decals,List<Map25DProjection> projected,List<string> exceptions){var spec=new Map25DProjection{spec=c};for(int mode=1;mode<=2;mode++){var mat=new Material(shader){name=c.id+(mode==2?" ground projection":"")};mat.SetTexture("_MainTex",Texture(c.asset));mat.SetTexture("_NormalTex",Texture(c.asset+"_normal"));mat.SetFloat("_Ground",0);mat.SetFloat("_ProjectionMode",c.type=="vegetation"?0:mode);mat.SetFloat("_Sway",c.sway);mat.SetVector("_SwayAnchor",new Vector4(c.drawX/100,0,-c.footY/100,1));mat.SetFloat("_SourcePlane",c.type=="vegetation"?0:1);mat.SetFloat("_Base",.22f);mat.SetFloat("_Emission",c.type=="m_c1camp"?.10f:c.type=="m_ctree15"?.07f:0);mat.SetFloat("_ZWrite",mode==1?0:1);mat.SetFloat("_DepthBias",mode==2?-1:0);mat.renderQueue=mode==1?(c.type=="vegetation"?2850:2800):2490;mat=Save(mat,"R3_"+c.id+"_projection_"+mode+".mat");var mesh=CardMesh(c.width/100,c.height/100,false);CullTransparentCells(mesh,Texture(c.asset));var go=MeshObject(c.id+(mode==2?" flat ground projection":""),mesh,mat,mode==1?cards:decals);go.transform.SetPositionAndRotation(new Vector3(c.drawX/100,0,-c.footY/100),Quaternion.Euler(55,0,0));if(mode==1)spec.body=go.transform;else{spec.ground=go.transform;go.SetActive(layout.groundConnections&&c.type!="vegetation");}}projected.Add(spec);exceptions.Add(c.id+" original="+c.x+","+c.y+" source="+c.width+"x"+c.height+" camera-ray Core mask: raised only on blocked pixels; walk copy has flat depth .018u");}
        static void BuildWebCard(Map25DCard c,Shader shader,Transform cards,Transform decals,List<string> exceptions){
            var source=Texture(c.asset);var pixels=source.GetPixels32();var raised=(Color32[])pixels.Clone();var flat=(Color32[])pixels.Clone();int walk=0,blocked=0;bool landmark=c.type!="boundary_tree";
            for(int y=0;y<source.height;y++)for(int x=0;x<source.width;x++){int i=y*source.width+x;float wx=c.drawX+(x/(float)(source.width-1)-.5f)*c.width,wy=c.footY-y/(float)(source.height-1)*c.height;bool onWalk=landmark&&map.CanMove(wx,wy,0);if(onWalk){raised[i].a=0;if(pixels[i].a>25)walk++;}else{flat[i].a=0;if(pixels[i].a>25)blocked++;}}
            Texture2D Make(Color32[] data,string suffix){var t=new Texture2D(source.width,source.height,TextureFormat.RGBA32,true){name=c.id+suffix,filterMode=FilterMode.Trilinear,wrapMode=TextureWrapMode.Clamp};t.SetPixels32(data);t.Apply();return Save(t,"R3_"+c.id+suffix+".asset");}
            var body=Make(raised,"_body");var mat=new Material(shader){name=c.id};mat.SetTexture("_MainTex",body);mat.SetTexture("_NormalTex",Texture(c.asset+"_normal"));mat.SetFloat("_Ground",0);mat.SetFloat("_Sway",c.sway);mat.SetVector("_SwayAnchor",new Vector4(c.drawX/100,0,-c.footY/100,1));mat.SetFloat("_Base",.22f);mat.SetFloat("_SourcePlane",1);mat.SetVector("_SourceRect",new Vector4(c.drawX/100,-c.footY/100,c.width/100,c.height/100));mat.SetFloat("_Emission",c.type=="m_c1camp"?.10f:c.type=="m_ctree15"?.07f:0);mat=Save(mat,"R3_"+c.id+".mat");
            mat.SetFloat("_ZWrite",0);mat.renderQueue=2800;EditorUtility.SetDirty(mat);var bodyMesh=CardMesh(c.width/100,c.height/100*Mathf.Sin(55*Mathf.Deg2Rad),false);CullTransparentCells(bodyMesh,body);
            var go=MeshObject(c.id,bodyMesh,mat,cards);float rootHeight=.014f;if(c.type=="boundary_tree"){float river=RiverCrossSection(c.drawX/100,-c.footY/100);if(river<1)rootHeight-=.39f*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.55f,1,river)));}go.transform.position=new Vector3(c.drawX/100,rootHeight,-c.footY/100);go.transform.rotation=Quaternion.Euler(55,0,0);go.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.Off;
            if(blocked>0&&(c.type=="m_c1camp"||c.type=="m_ctree15"||c.type=="m_sword_pile")){var anchor=new Material(mat){name=c.id+" original blocked ground footprint"};anchor.SetFloat("_ZWrite",1);anchor.SetFloat("_Sway",0);anchor.renderQueue=2450;anchor=Save(anchor,"R3_"+c.id+"_blocked_footprint.mat");var mesh=CardMesh(c.width/100,c.height/100,false);CullTransparentCells(mesh,body);var a=MeshObject(c.id+" original blocked footprint",mesh,anchor,world);a.transform.SetPositionAndRotation(new Vector3(c.drawX/100,.04f,-c.footY/100),Quaternion.Euler(90,0,0));}
            if(walk>0){var painting=Make(flat,"_walk_paint");var dm=new Material(shader){name=c.id+" original ground connection"};dm.SetTexture("_MainTex",painting);dm.SetTexture("_NormalTex",Texture(c.asset+"_normal"));dm.SetFloat("_Base",.22f);dm.SetFloat("_SourcePlane",1);dm.SetVector("_SourceRect",new Vector4(c.drawX/100,-c.footY/100,c.width/100,c.height/100));dm.SetFloat("_Ground",0);dm.SetFloat("_Emission",c.type=="m_c1camp"?.10f:c.type=="m_ctree15"?.07f:0);dm=Save(dm,"R3_"+c.id+"_walk_paint.mat");var d=MeshObject(c.id+" flat walking connection",CardMesh(c.width/100,c.height/100,false),dm,decals);d.transform.position=new Vector3(c.drawX/100,.018f,-c.footY/100);d.transform.rotation=Quaternion.Euler(90,0,0);}
            exceptions.Add(c.id+" type="+c.type+" originalAnchor="+c.x+","+c.y+" visible="+c.width+"x"+c.height+" raisedBlockedPixels="+blocked+" flattenedWalkPixels="+walk);
        }
        static void CullTransparentCells(Mesh mesh,Texture2D texture){
            int w=texture.width,h=texture.height,stride=w+1;var pixels=texture.GetPixels32();var sum=new int[(w+1)*(h+1)];for(int y=0;y<h;y++){int row=0;for(int x=0;x<w;x++){if(pixels[y*w+x].a>8)row++;sum[(y+1)*stride+x+1]=sum[y*stride+x+1]+row;}}
            var uv=mesh.uv;var indices=mesh.triangles;var kept=new List<int>();for(int i=0;i<indices.Length;i+=3){var a=uv[indices[i]];var b=uv[indices[i+1]];var c=uv[indices[i+2]];int x0=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(a.x,Mathf.Min(b.x,c.x))*(w-1)),0,w),x1=Mathf.Clamp(Mathf.CeilToInt(Mathf.Max(a.x,Mathf.Max(b.x,c.x))*(w-1))+1,0,w),y0=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(a.y,Mathf.Min(b.y,c.y))*(h-1)),0,h),y1=Mathf.Clamp(Mathf.CeilToInt(Mathf.Max(a.y,Mathf.Max(b.y,c.y))*(h-1))+1,0,h);if(sum[y1*stride+x1]-sum[y0*stride+x1]-sum[y1*stride+x0]+sum[y0*stride+x0]==0)continue;kept.Add(indices[i]);kept.Add(indices[i+1]);kept.Add(indices[i+2]);}mesh.SetTriangles(kept,0);mesh.RecalculateBounds();
        }

        [Serializable] sealed class R4Forms {public R4Rock[] rocks;public R4Log[] logs;public R4Mound[] mounds;public R4BankPatch[] bankPatches;}
        [Serializable] sealed class R4BankPatch {public int side;public float from,to;}
        [Serializable] sealed class R4Rock {public string id;public float x,y,rx,rz,height,phase;}
        [Serializable] sealed class R4Log {public string id;public float x,y,length,radius,height,yaw;public bool vertical;}
        [Serializable] sealed class R4Mound {public float x,y,rx,rz,height;}
        static float Round4GroundHeight(float x,float py){
            for(int yy=-1;yy<=1;yy++)for(int xx=-1;xx<=1;xx++)if(map.CanMove(x*100+xx*40,py*100+yy*40,0))return 0;
            float height=0;foreach(var m in r4Forms.mounds){float qx=(x*100-m.x)/m.rx,qy=(py*100-m.y)/m.rz,d=qx*qx+qy*qy;if(d<1)height+=m.height/100*Mathf.Pow(1-d,2);}
            float river=RiverCrossSection(x,-py);if(river<.65f)height=Mathf.Min(height,-.12f*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.35f,.65f,river))));return height;
        }
        static Material Round4SolidMaterial(string source,Color tint,float wet){var shader=Resources.Load<Shader>("Map25D/R4Solid");if(shader==null||ShaderUtil.ShaderHasError(shader))throw new Exception("R4 triplanar shader invalid");var mat=new Material(shader){name="R4 painted solid "+source};mat.SetTexture("_MainTex",Texture("r4_tex_"+source));mat.SetTexture("_NormalTex",Texture("r4_tex_"+source+"_normal"));mat.SetColor("_Tint",tint);mat.SetFloat("_Base",.22f);mat.SetFloat("_Ground",0);mat.SetFloat("_Wetness",wet);mat.SetFloat("_Tiling",.65f);return Save(mat,"R4_solid_"+source+".mat");}
        static void ValidateRound4Solid(GameObject go){var mesh=go.GetComponent<MeshFilter>().sharedMesh;var v=mesh.vertices;var used=new HashSet<int>(mesh.triangles);foreach(int i in used){var q=go.transform.TransformPoint(v[i]);if(float.IsNaN(q.x)||float.IsNaN(q.y)||float.IsNaN(q.z))throw new Exception("Nonfinite solid "+go.name);if(map.CanMove(q.x*100,-q.z*100,0))throw new Exception("Solid reaches original walk: "+go.name+" "+q);}}
        static void BuildRound4Solids(){
            var parent=new GameObject("Solid forms").transform;parent.SetParent(world,false);var rock=Round4SolidMaterial("rock",new Color(.68f,.76f,.74f,1),.30f);var wood=Round4SolidMaterial("bark",new Color(.78f,.70f,.58f,1),.15f);var mud=Round4SolidMaterial("mud",new Color(.70f,.63f,.48f,1),.24f);
            foreach(var r in r4Forms.rocks){var go=MeshObject(r.id,Round4RockMesh(r),rock,parent);go.transform.position=new Vector3(r.x/100,Round4GroundHeight(r.x/100,r.y/100)-.025f,-r.y/100);ValidateRound4Solid(go);}
            foreach(var r in r4Forms.logs){var go=MeshObject(r.id,Round4LogMesh(r),wood,parent);go.transform.SetPositionAndRotation(new Vector3(r.x/100,r.height/100,-r.y/100),Quaternion.Euler(0,r.yaw,r.vertical?90:0));ValidateRound4Solid(go);}
            for(int side=-1;side<=1;side+=2){var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();int row=0;for(int s=0;s+1<layout.riverPoints.Length;s++)for(int k=0;k<=24;k++){var q=RiverSample(s,k/24f);for(int j=0;j<=6;j++){float fade=0;foreach(var patch in r4Forms.bankPatches)if(patch.side==side&&q.y>=patch.from&&q.y<=patch.to)fade=Mathf.Max(fade,Mathf.Min(Mathf.InverseLerp(patch.from,patch.from+40,q.y),Mathf.InverseLerp(patch.to,patch.to-40,q.y)));float a=j/6f,du=.70f+.30f*a,x=(q.x+side*q.z*du)/100,z=-q.y/100,h=Round4GroundHeight(x,-z)+.04f+.25f*fade*Mathf.Sin(a*Mathf.PI)*(.85f+.15f*Mathf.Sin(q.y*.006f));v.Add(new Vector3(x,h,z));uv.Add(new Vector2(x,z));}bool permitted=false;foreach(var patch in r4Forms.bankPatches)if(patch.side==side&&q.y>=patch.from&&q.y<=patch.to)permitted=true;if(row>0&&permitted)for(int j=0;j<6;j++){int n=row*7+j;var ids=new[]{n-7,n-6,n,n-6,n+1,n};for(int a=0;a<6;a+=3){bool clear=true;Vector3 center=Vector3.zero;for(int b=0;b<3;b++){var p=v[ids[a+b]];center+=p;if(map.CanMove(p.x*100,-p.z*100,0))clear=false;}center/=3;if(map.CanMove(center.x*100,-center.z*100,0))clear=false;if(clear)tri.AddRange(new[]{ids[a],ids[a+1],ids[a+2]});}}row++;}var mesh=new Mesh{name="Curved raised root mud bank"};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();var go=MeshObject("Raised root mud bank "+side,mesh,mud,parent);ValidateRound4Solid(go);}
            File.WriteAllText(Path.Combine(Output,"r4-solid-contract.json"),"{\"rockGroups\":3,\"rocks\":"+r4Forms.rocks.Length+",\"logs\":"+r4Forms.logs.Length+",\"raisedBanks\":2,\"newColliders\":0,\"referencedSolidVerticesOnCoreWalk\":0,\"walkTerrainGuardPx\":40,\"source\":\"existing web painting crops, triplanar, no paid generation\"}");
        }
        static Mesh Round4RockMesh(R4Rock spec){const int nx=14;float[] ringY={0,.12f,.40f,.76f,.96f},ringR={.72f,1,.98f,.79f,.36f};var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();for(int y=0;y<5;y++)for(int x=0;x<=nx;x++){float u=x/(float)nx,a=u*Mathf.PI*2,r=ringR[y]*(1+.10f*Mathf.Sin(a*3+spec.phase)+.055f*Mathf.Cos(a*5-y));v.Add(new Vector3(Mathf.Cos(a)*spec.rx/100*r+(y/4f)*.07f,ringY[y]*spec.height/100+(y==0?0:.025f*Mathf.Sin(a*4+spec.phase)),Mathf.Sin(a)*spec.rz/100*r));uv.Add(new Vector2(u,y/4f));}for(int y=0;y<4;y++)for(int x=0;x<nx;x++){int a=y*(nx+1)+x;tri.AddRange(new[]{a,a+nx+1,a+1,a+1,a+nx+1,a+nx+2});}int top=v.Count;v.Add(new Vector3(.07f,spec.height/100,0));uv.Add(new Vector2(.5f,1));for(int x=0;x<nx;x++)tri.AddRange(new[]{top,4*(nx+1)+x+1,4*(nx+1)+x});var mesh=new Mesh{name="Weathered bevel rock "+spec.id};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();return mesh;}
        static Mesh Round4LogMesh(R4Log spec){const int nx=20,ny=10;var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();for(int shell=0;shell<2;shell++)for(int j=0;j<=ny;j++)for(int i=0;i<=nx;i++){float u=i/(float)nx,t=j/(float)ny,a=u*Mathf.PI*2,r=spec.radius/100*(.92f+.075f*Mathf.Sin(a*3+t*4)+.04f*Mathf.Cos(a*7-t*8))*(shell==0?1:.62f),fracture=(j==0||j==ny)?.12f*Mathf.Sin(a*5):0;v.Add(new Vector3(t*spec.length/100+fracture,.055f*Mathf.Sin(t*Mathf.PI)+Mathf.Cos(a)*r,.07f*Mathf.Sin(t*Mathf.PI*2)+Mathf.Sin(a)*r));uv.Add(new Vector2(u,t));}int stride=(nx+1)*(ny+1);for(int shell=0;shell<2;shell++)for(int j=0;j<ny;j++)for(int i=0;i<nx;i++){int a=shell*stride+j*(nx+1)+i;if(shell==0)tri.AddRange(new[]{a,a+1,a+nx+1,a+1,a+nx+2,a+nx+1});else tri.AddRange(new[]{a,a+nx+1,a+1,a+1,a+nx+1,a+nx+2});}for(int end=0;end<2;end++)for(int i=0;i<nx;i++){int a=end*ny*(nx+1)+i,b=a+stride;if(end==0)tri.AddRange(new[]{a,b,a+1,a+1,b,b+1});else tri.AddRange(new[]{a,a+1,b,a+1,b+1,b});}var mesh=new Mesh{name="Broken hollow painted log "+spec.id};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();return mesh;}
        static void BuildRound4Card(Map25DCard c,Shader shader,Transform parent,List<Map25DProjection> props){
            var mat=new Material(shader){name=c.id};mat.SetTexture("_MainTex",Texture(c.asset));mat.SetTexture("_NormalTex",Texture(c.asset+"_normal"));mat.SetFloat("_Ground",0);mat.SetFloat("_SourcePlane",0);mat.SetFloat("_ForestWall",c.type=="forest_wall"?1:0);mat.SetFloat("_ProjectionMode",0);mat.SetFloat("_Sway",c.sway);mat.SetFloat("_Base",.20f);mat.SetFloat("_TreePalette",c.type.StartsWith("m_ctree",StringComparison.Ordinal)&&c.type!="m_ctree15"?1:0);mat.SetFloat("_Emission",c.type=="m_c1camp"?.10f:c.type=="m_ctree15"?.12f:0);mat.SetFloat("_ZWrite",c.layer=="low"?0:1);mat.renderQueue=c.layer=="low"?2470:2450;mat=Save(mat,"R4_"+c.id+".mat");var mesh=CardMesh(c.width/100,c.height/100,false);CullTransparentCells(mesh,Texture(c.asset));var go=MeshObject(c.id,mesh,mat,parent);go.transform.SetPositionAndRotation(new Vector3(c.drawX/100,layout.round5?world.GetComponent<Map25DEnvironment>().HeightSurface.SampleHeight(new Vector3(c.drawX/100,0,-c.footY/100))+world.GetComponent<Map25DEnvironment>().HeightSurface.transform.position.y:0,-c.footY/100),Quaternion.Euler(layout.cameraPitch,layout.cameraYaw,0));if(c.type=="vegetation")go.transform.localScale=new Vector3(1,Mathf.Min(1,.9f/(c.height/100)),1);props.Add(new Map25DProjection{body=go.transform,spec=c});if(c.type.StartsWith("m_ctree",StringComparison.Ordinal)){var contact=MeshObject("Visible tree foot contact "+c.id,UnitQuad(),Save(new Material(Resources.Load<Shader>("Map25D/FootContact")){name="Tree foot contact "+c.id},"TreeContact_"+c.id+".mat"),parent);contact.transform.SetPositionAndRotation(go.transform.position+Vector3.up*.009f,Quaternion.Euler(90,0,0));contact.transform.localScale=new Vector3(c.width/100*.38f,c.width/100*.20f,1);contact.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.Off;}
        }
        static void BuildRound4Pipeline(){
            var pipeline=Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Exoduser/Rendering/URP_PC_High.asset"));pipeline.name="Map25D R4 isolated pipeline";var renderer=Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRendererData>("Assets/Exoduser/Rendering/URP_PC_High_Renderer.asset"));renderer.name="Map25D R4 isolated renderer";renderer.rendererFeatures.RemoveAll(feature=>feature!=null&&feature.GetType().Name=="HellFogFeature");var rs=new SerializedObject(renderer);rs.FindProperty("m_CopyDepthMode").intValue=0;rs.ApplyModifiedPropertiesWithoutUndo();renderer=Save(renderer,"R4Renderer.asset",Res);var tiltMaterial=new Material(Resources.Load<Shader>("Map25D/R4TiltShift")){name="R4 Gaussian band tilt shift"};tiltMaterial=Save(tiltMaterial,"R4TiltShift.mat",Res);FullScreenPassRendererFeature tilt=null;foreach(var asset in AssetDatabase.LoadAllAssetsAtPath(Res+"/R4Renderer.asset"))if(asset is FullScreenPassRendererFeature feature&&feature.name=="R4 tilt shift")tilt=feature;if(tilt==null){tilt=ScriptableObject.CreateInstance<FullScreenPassRendererFeature>();tilt.name="R4 tilt shift";AssetDatabase.AddObjectToAsset(tilt,renderer);}tilt.injectionPoint=FullScreenPassRendererFeature.InjectionPoint.BeforeRenderingPostProcessing;tilt.fetchColorBuffer=true;tilt.requirements=ScriptableRenderPassInput.None;tilt.passMaterial=tiltMaterial;tilt.passIndex=0;tilt.Create();renderer.rendererFeatures.Add(tilt);EditorUtility.SetDirty(tilt);EditorUtility.SetDirty(renderer);var copyMaterial=new Material(Resources.Load<Shader>("Map25D/R4DepthCopy")){name="R4 linear world depth copy"};copyMaterial=Save(copyMaterial,"R4DepthCopy.mat",Res);R4WorldDepth depth=null;foreach(var asset in AssetDatabase.LoadAllAssetsAtPath(Res+"/R4Renderer.asset"))if(asset is R4WorldDepth f)depth=f;if(depth==null){depth=ScriptableObject.CreateInstance<R4WorldDepth>();depth.name="R4 preserved world depth";AssetDatabase.AddObjectToAsset(depth,renderer);}depth.CopyMaterial=copyMaterial;depth.Create();renderer.rendererFeatures.Add(depth);EditorUtility.SetDirty(depth);EditorUtility.SetDirty(renderer);var overlay=Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRendererData>("Assets/Exoduser/Rendering/URP_PC_High_Renderer.asset"));overlay.name="R4 sharp orthographic actors";overlay.rendererFeatures.Clear();overlay=Save(overlay,"R4OverlayRenderer.asset",Res);var so=new SerializedObject(pipeline);var list=so.FindProperty("m_RendererDataList");list.arraySize=2;list.GetArrayElementAtIndex(0).objectReferenceValue=renderer;list.GetArrayElementAtIndex(1).objectReferenceValue=overlay;so.FindProperty("m_RequireDepthTexture").boolValue=true;so.FindProperty("m_MainLightShadowmapResolution").intValue=4096;so.FindProperty("m_ShadowDistance").floatValue=65;so.FindProperty("m_MSAA").intValue=1;so.ApplyModifiedPropertiesWithoutUndo();Save(pipeline,"R4Pipeline.asset",Res);
        }
        static void BuildRound4KeyLight(){
            var light=new GameObject("R4 warm camp shaft").AddComponent<Light>();light.transform.SetParent(world,false);light.type=LightType.Spot;light.transform.position=new Vector3(9,8,-39);light.transform.rotation=Quaternion.LookRotation(new Vector3(20.5f,0,-43)-light.transform.position);light.range=24;light.spotAngle=28;light.innerSpotAngle=18;light.intensity=180;light.color=new Color(1,.57f,.23f);var cookie=new Texture2D(256,256,TextureFormat.RGBA32,false,true){name="R4 soft path slit cookie",wrapMode=TextureWrapMode.Clamp,filterMode=FilterMode.Bilinear};var pixels=new Color32[256*256];for(int y=0;y<256;y++)for(int x=0;x<256;x++){float u=(x+.5f)/256,v=(y+.5f)/256,axis=u-.5f-.045f*Mathf.Sin(v*7);float a=Mathf.Exp(-Mathf.Pow(axis/.22f,4))*Mathf.SmoothStep(0,1,v/.08f)*Mathf.SmoothStep(0,1,(1-v)/.08f);float twig=Mathf.Exp(-Mathf.Pow((v-.35f-.12f*u)/.018f,2));a*=1-.7f*twig;byte b=(byte)(a*255);pixels[y*256+x]=new Color32(b,b,b,255);}cookie.SetPixels32(pixels);cookie.Apply();light.cookie=Save(cookie,"R4_light_cookie.asset");light.shadows=LightShadows.Soft;light.shadowBias=.025f;light.shadowNormalBias=.04f;
            // Warmth is restricted to the soft cookie on ground; no air beam across the river.
