        static void BuildOuterForest(Shader shader,Transform ground,Transform cards){
            var earth=new Material(shader){name="Outside map web earth apron"};earth.SetTexture("_MainTex",Texture("r3_soil"));earth.SetTexture("_NormalTex",Texture("r3_ground_0_3_normal"));earth.SetFloat("_Ground",0);earth.SetFloat("_Base",.12f);earth=Save(earth,"R3_outer_earth.mat");
