        static void Card(Map25DCard c,Transform parent)
        {
            var tex=Texture(c.asset);var go=new GameObject(c.id);go.transform.SetParent(parent,false);
            bool flat=c.layer=="ground";float w=c.width/100,h=c.height/100;
            var tint=c.tint??new[]{1f,1f,1f};var mat=Material(c.id,c.asset,0,new Color(tint[0],tint[1],tint[2]),c.sway);
            mat.SetFloat("_Emissive",c.id=="m_c1camp"?.36f:c.id=="m_ctree15"?.70f:0);
            float footY=c.y+(c.layer=="authored"?c.height*.5f:0);
            go.transform.position=new Vector3(c.x/100,flat?.018f:Height(c.x/100,-footY/100),-footY/100);
            go.transform.rotation=flat?Quaternion.Euler(90,c.rotation,0):c.layer=="panel"?Quaternion.Euler(0,layout.cameraYaw,0):Quaternion.Euler(0,layout.cameraYaw,0)*NativeRemodelCamera.Rotation;
            mat.SetFloat("_Panel",c.layer=="panel"?1:0);
            var mesh=CardMesh(w,h,flat);
            // Trim actual alpha geometry; foreground is also clipped out of the original Core walk area.
            var vertices=mesh.vertices;var uv=mesh.uv;var indices=mesh.triangles;var clipped=new List<int>();
            for(int t=0;t<indices.Length;t+=3){int a=indices[t],b=indices[t+1],d=indices[t+2];var sample=(uv[a]+uv[b]+uv[d])/3;bool opaque=tex.GetPixelBilinear(sample.x,sample.y).a>.09f;
                // Pixel alpha clips in the shader. Centroid-only triangle pruning cut thin painted branches into stairs.
                if(c.layer=="foreground"||c.layer=="panel"){
                    bool walk=false;foreach(int vi in new[]{a,b,d}){var wp=go.transform.TransformPoint(vertices[vi]);if(map.CanMove(wp.x*100,-wp.z*100,45))walk=true;}if(walk)continue;
                }
                clipped.Add(a);clipped.Add(b);clipped.Add(d);
            }
            mesh.SetTriangles(clipped,0);mesh.RecalculateBounds();mesh=Save(mesh,"C_"+c.id+".asset");go.AddComponent<MeshFilter>().sharedMesh=mesh;
            var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterial=mat;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;
            // Every card has a broad, soft ground contact. No geometric prop or new collider is added.
            if(!flat&&c.layer!="panel"){var shadow=new GameObject("Contact "+c.id);shadow.transform.SetParent(parent,false);shadow.transform.position=go.transform.position+new Vector3(0,.012f,0);shadow.transform.rotation=Quaternion.Euler(90,0,0);shadow.transform.localScale=new Vector3(w*.68f,w*.22f,1);
                var sr=shadow.AddComponent<MeshRenderer>();var sm=new Material(Resources.Load<Shader>("Map25D/Painted")){name="Map25D black foot contact"};sm.SetFloat("_Kind",3);sm.SetFloat("_ZWrite",0);sm.renderQueue=2980;sm=Save(sm,"S_"+c.id+".mat");sr.sharedMaterial=sm;sr.shadowCastingMode=ShadowCastingMode.Off;var mf=shadow.AddComponent<MeshFilter>();mf.sharedMesh=UnitQuad();}
        }
        static Mesh CardMesh(float w,float h,bool flat){var mesh=new Mesh{name="Painted card root fixed"};var vs=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();int nx=32,ny=40;for(int y=0;y<=ny;y++)for(int x=0;x<=nx;x++){vs.Add(new Vector3((x/(float)nx-.5f)*w,(y/(float)ny-(flat?.5f:0))*h,0));uv.Add(new Vector2(x/(float)nx,y/(float)ny));}for(int y=0;y<ny;y++)for(int x=0;x<nx;x++){int a=y*(nx+1)+x;tri.AddRange(new[]{a,a+nx+1,a+1,a+1,a+nx+1,a+nx+2});}mesh.SetVertices(vs);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();return mesh;}
