            var mat=Material("blocked-root-painting","prop_g_root",4,Color.white,0);mat.SetTexture("_FloorTex",Texture("r2_ground"));mat.SetVector("_GroundRect",new Vector4(-10,24,60,36));mat.SetFloat("_DepthBias",-1);mat.renderQueue=2480;
