                for(int j=0;j<=rings;j++)for(int i=0;i<=segments;i++){float r=j/(float)rings*1.035f,angle=i/(float)segments*Mathf.PI*2,xx=Mathf.Cos(angle)*r,yy=Mathf.Sin(angle)*r,x=(c.x+xx*c.rx)/100,z=-(c.y+yy*c.ry)/100;float h=.42f*Mathf.Pow(Mathf.Clamp01(1-r*r/(.86f*.86f)),.65f);if(map.CanMove(x*100,-z*100,0))h=0;v.Add(new Vector3(x,h,z));uv.Add(new Vector2(.5f+xx*.48f,.5f-yy*.48f));}
                for(int j=0;j<rings;j++)for(int i=0;i<segments;i++){int n=j*(segments+1)+i;tri.AddRange(new[]{n,n+segments+1,n+1,n+1,n+segments+1,n+segments+2});}
                var mesh=new Mesh{name="Original ellipse root terrain "+c.x+" "+c.y};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();MeshObject("Blocked roots "+c.x+" "+c.y,mesh,mat,parent);
            }
