        static float RiverDistance(float x,float z)
        {
            float result=1000;var p=new Vector2(x,-z);
            for(int i=0;i+1<layout.riverPoints.Length;i++){var a=layout.riverPoints[i];var b=layout.riverPoints[i+1];var pa=new Vector2(a.x,a.y)/100;var pb=new Vector2(b.x,b.y)/100;float t=Mathf.Clamp01(Vector2.Dot(p-pa,pb-pa)/(pb-pa).sqrMagnitude);result=Mathf.Min(result,Vector2.Distance(p,Vector2.Lerp(pa,pb,t))-Mathf.Lerp(a.width,b.width,t)/100);}
            return result;
        }
        static float Height(float x,float z)
        {
            // A continuous distance to walk rectangles replaces the hard dilated-tile height step.
            int tx=Mathf.FloorToInt(x/.4f),ty=Mathf.FloorToInt(-z/.4f);if(tx>=0&&tx<200&&ty>=0&&ty<200&&map.Data.tiles[ty*200+tx]==0)return 0;
            float nearest=10000,py=-z;
            if(tx>=-5&&tx<205&&ty>=-5&&ty<205)for(int j=-5;j<=5;j++)for(int i=-5;i<=5;i++){int xx=tx+i,yy=ty+j;if(xx<0||xx>=200||yy<0||yy>=200||map.Data.tiles[yy*200+xx]!=0)continue;float dx=Mathf.Max(xx*.4f-x,Mathf.Max(x-(xx+1)*.4f,0)),dy=Mathf.Max(yy*.4f-py,Mathf.Max(py-(yy+1)*.4f,0));nearest=Mathf.Min(nearest,dx*dx+dy*dy);}
            float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.85f,1.65f,Mathf.Sqrt(nearest)));
            float d=RiverDistance(x,z),height=d<.25f?Mathf.Lerp(-.82f,.04f,Mathf.SmoothStep(0,1,(d+.2f)/.45f)):.07f+.13f*Mathf.Sin(x*.37f+z*.18f)+.10f*Mathf.Sin(z*.54f-x*.21f);
            return height*blend;
        }
        static Mesh Grid(float x0,float z0,float x1,float z1,int nx,int ny){var m=new Mesh{indexFormat=IndexFormat.UInt32};var vs=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();for(int y=0;y<=ny;y++)for(int x=0;x<=nx;x++){float wx=Mathf.Lerp(x0,x1,x/(float)nx),wz=Mathf.Lerp(z0,z1,y/(float)ny);vs.Add(new Vector3(wx,Height(wx,wz),wz));uv.Add(new Vector2(wx,wz));}for(int y=0;y<ny;y++)for(int x=0;x<nx;x++){int a=y*(nx+1)+x;tri.AddRange(new[]{a,a+nx+1,a+1,a+1,a+nx+1,a+nx+2});}m.SetVertices(vs);m.SetUVs(0,uv);m.SetTriangles(tri,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();return m;}
        static GameObject MeshObject(string name,Mesh mesh,Material mat,Transform parent){if(AssetDatabase.Contains(mesh))mesh=Object.Instantiate(mesh);mesh=Save(mesh,"Mesh_"+(serial++)+".asset");var o=new GameObject(name);o.transform.SetParent(parent,false);o.AddComponent<MeshFilter>().sharedMesh=mesh;var r=o.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=layout.round4&&parent.name!="Ground"?ShadowCastingMode.TwoSided:ShadowCastingMode.Off;r.receiveShadows=true;return o;}
        static void BuildRiver(Map25DEnvironment env)
        {
            var mat=Material("river","soil",2,Color.white,0);env.Water=mat;var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();
            var points=layout.riverPoints;int index=0;
            for(int s=0;s+1<points.Length;s++)for(int k=0;k<=20;k++){
                var sample=RiverSample(s,k/20f);float x=sample.x,y=sample.y,width=sample.z,zz=-y/100;
                for(int j=0;j<=12;j++){float u=j/12f;v.Add(new Vector3((x+(u*2-1)*width)/100,-.55f,zz));uv.Add(new Vector2(u,y/200));}
                if(index>0)for(int j=0;j<12;j++){int n=index*13+j;tri.AddRange(new[]{n-13,n-12,n,n-12,n+1,n});}index++;
            }
            var mesh=new Mesh{name="Authored blocked-side flow ribbon"};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();var go=MeshObject("Poison river",mesh,mat,world);go.layer=4;
            var bankMat=Material("muddy-banks","r2_ground",1,new Color(.57f,.52f,.40f),0);bankMat.SetVector("_GroundRect",new Vector4(-10,24,60,36));bankMat.SetTexture("_FloorTex",Texture("soil"));bankMat.SetTexture("_FloorNormal",Texture("soil_normal"));bankMat.SetFloat("_DepthBias",-1);bankMat.renderQueue=2490;
            var ground=world.Find("Ground");
            foreach(int side in new[]{-1,1}){var bv=new List<Vector3>();var buv=new List<Vector2>();var bt=new List<int>();int row=0;
                for(int s=0;s+1<points.Length;s++)for(int k=0;k<=20;k++){
                    var p=RiverSample(s,k/20f);for(int j=0;j<=4;j++){float edge=j/4f,offset=Mathf.Lerp(-6,145,edge),wx=(p.x+side*(p.z+offset))/100,wz=-p.y/100;float ripple=.08f*Mathf.Sin(p.y*.008f+side)*Mathf.Sin(edge*Mathf.PI);float yy=Mathf.Lerp(-.57f,Height(wx,wz),Mathf.SmoothStep(0,1,edge))+ripple;if(map.CanMove(wx*100,-wz*100,30))yy=Mathf.Min(0,yy);bv.Add(new Vector3(wx,yy,wz));buv.Add(new Vector2(wx,wz));}
                    if(row>0)for(int j=0;j<4;j++){int n=row*5+j;bt.AddRange(new[]{n-5,n-4,n,n-4,n+1,n});}row++;
                }
                var bm=new Mesh{name="Curved submerged-to-mud bank "+side};bm.SetVertices(bv);bm.SetUVs(0,buv);bm.SetTriangles(bt,0);bm.RecalculateNormals();bm.RecalculateTangents();bm.RecalculateBounds();MeshObject("Bank "+side,bm,bankMat,ground);
            }
        }
        static Vector3 RiverSample(int segment,float t){var p=layout.riverPoints;Vector3 A(int i){var r=p[Mathf.Clamp(i,0,p.Length-1)];return new Vector3(r.x,r.y,r.width);}var a=A(segment-1);var b=A(segment);var c=A(segment+1);var d=A(segment+2);var q=.5f*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);q.x+=24*Mathf.Sin(q.y*.007f)+12*Mathf.Sin(q.y*.015f);q.z+=28*Mathf.Sin(q.y*.0055f)+18*Mathf.Cos(q.y*.012f);return q;}
        [Serializable] sealed class CameraOcclusionReceipt{public float yaw;public int walkTiles,rays,blockedTiles;public List<string> samples=new List<string>();public string scope="actual yaw camera-to-capsule triangle intersections; complements canonical north-facing MapLint L1b/L4; no physics collider added";}
        sealed class RayMesh{public Bounds bounds;public Vector3[] vertices;public int[] triangles;public string name;}
        static void CameraOcclusionCheck(){var meshes=new List<RayMesh>();foreach(var r in world.Find("Painted cards").GetComponentsInChildren<MeshRenderer>()){if(r.name.StartsWith("Contact ",StringComparison.Ordinal))continue;var m=r.GetComponent<MeshFilter>().sharedMesh;var v=m.vertices;for(int i=0;i<v.Length;i++)v[i]=r.transform.TransformPoint(v[i]);meshes.Add(new RayMesh{bounds=r.bounds,vertices=v,triangles=m.triangles,name=r.name});}
            var result=new CameraOcclusionReceipt{yaw=layout.cameraYaw};var q=Quaternion.Euler(0,layout.cameraYaw,0);var offset=q*ViewOffset();
            for(int ty=layout.window[1];ty<layout.window[3];ty++)for(int tx=layout.window[0];tx<layout.window[2];tx++){float x=(tx+.5f)*.4f,z=-(ty+.5f)*.4f;if(!map.CanMove(x*100,-z*100,0))continue;result.walkTiles++;bool blocked=false;var foot=new Vector3(x,0,z);foreach(float h in new[]{.25f,1f,1.6f}){result.rays++;var origin=foot+Vector3.up*h;var delta=foot+offset-origin;float distance=delta.magnitude;var ray=new Ray(origin,delta/distance);foreach(var mesh in meshes){if(!mesh.bounds.IntersectRay(ray,out float near)||near>distance)continue;for(int i=0;i<mesh.triangles.Length;i+=3)if(RayTriangle(ray,distance,mesh.vertices[mesh.triangles[i]],mesh.vertices[mesh.triangles[i+1]],mesh.vertices[mesh.triangles[i+2]])){blocked=true;if(result.samples.Count<12)result.samples.Add(tx+","+ty+":"+mesh.name);break;}if(blocked)break;}if(blocked)break;}if(blocked)result.blockedTiles++;}
            File.WriteAllText(Path.Combine(Output,"actual-camera-occlusion.json"),JsonUtility.ToJson(result,true));
        }
        static bool RayTriangle(Ray ray,float distance,Vector3 a,Vector3 b,Vector3 c){var e1=b-a;var e2=c-a;var p=Vector3.Cross(ray.direction,e2);float det=Vector3.Dot(e1,p);if(Mathf.Abs(det)<.000001f)return false;float inv=1/det;var s=ray.origin-a;float u=Vector3.Dot(s,p)*inv;if(u<0||u>1)return false;var q=Vector3.Cross(s,e1);float v=Vector3.Dot(ray.direction,q)*inv;if(v<0||u+v>1)return false;float d=Vector3.Dot(e2,q)*inv;return d>.02f&&d<distance-.02f;}
        static void BuildLighting(Map25DEnvironment env)
        {
