        static void InspectUnitySources(){
            var receipt=new UnitySourceReceipt();var terrain=AssetDatabase.LoadAssetAtPath<TerrainData>("Assets/Exoduser/Remodel/CH1_1/Generated/RM1_Terrain.asset");if(terrain!=null){receipt.terrainSize=terrain.size;receipt.terrainResolution=terrain.heightmapResolution;}
            foreach(var name in new[]{"RF3_Ancient_Tree_A","RF3_Ancient_Tree_B","RF3_Rotten_Wood_Bridge","RF3_Root_Stump","RF3_Moss_Rock_1","RF3_Fallen_Log"}){var prefab=Resources.Load<GameObject>("Art/map/a2/r3/Models/"+name);if(prefab==null)continue;var go=Object.Instantiate(prefab);go.transform.position=Vector3.zero;var renderers=go.GetComponentsInChildren<Renderer>();if(renderers.Length==0){Object.DestroyImmediate(go);continue;}var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);var item=new UnitySourceModel{name=name,centre=bounds.center,size=bounds.size,renderers=renderers.Length,centreSurface=-999};foreach(var filter in go.GetComponentsInChildren<MeshFilter>()){if(filter.sharedMesh!=null)item.vertices+=filter.sharedMesh.vertexCount;}
                if(name.Contains("Bridge")){var probes=new List<MeshCollider>();foreach(var filter in go.GetComponentsInChildren<MeshFilter>())if(filter.sharedMesh!=null&&filter.sharedMesh.isReadable){var collider=filter.gameObject.AddComponent<MeshCollider>();collider.sharedMesh=filter.sharedMesh;probes.Add(collider);}Physics.SyncTransforms();float highest=float.NegativeInfinity;foreach(var offset in new[]{Vector2.zero,new Vector2(.08f,0),new Vector2(-.08f,0),new Vector2(0,.08f)}){var ray=new Ray(new Vector3(bounds.center.x+offset.x,bounds.max.y+2,bounds.center.z+offset.y),Vector3.down);foreach(var probe in probes)if(probe.Raycast(ray,out var hit,bounds.size.y+4))highest=Mathf.Max(highest,hit.point.y);}if(!float.IsNegativeInfinity(highest))item.centreSurface=highest;}
                receipt.models.Add(item);Object.DestroyImmediate(go);
