        static Material GB1Material(string name,Color color){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="GB1 solid "+name,enableInstancing=true};m.SetColor("_BaseColor",color);m.SetFloat("_Smoothness",.05f);m.SetFloat("_Metallic",0);return Save(m,"Grey_"+name+".mat");}
        static GameObject GB1Place(string name,PrimitiveType type,Vector3 pos,Vector3 scale,Material material,Transform parent,bool slope){RaycastHit hit;if(!Physics.Raycast(pos+Vector3.up*60,Vector3.down,out hit,120,1<<28,QueryTriggerInteraction.Ignore))throw new Exception("GB1 ground ray missed "+name+" "+pos);var root=new GameObject(name);root.transform.SetParent(parent,false);root.transform.position=hit.point-Vector3.up*.04f;if(slope){var q=Quaternion.FromToRotation(Vector3.up,hit.normal);root.transform.rotation=Quaternion.RotateTowards(Quaternion.identity,q,15);}var body=GameObject.CreatePrimitive(type);Object.DestroyImmediate(body.GetComponent<Collider>());body.transform.SetParent(root.transform,false);body.transform.localScale=scale;float half=type==PrimitiveType.Cylinder||type==PrimitiveType.Capsule?scale.y:scale.y*.5f;body.transform.localPosition=new Vector3(0,half,0);var r=body.GetComponent<MeshRenderer>();r.sharedMaterial=material;r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;var grounding=root.AddComponent<GB1Grounded>();grounding.hitPoint=hit.point;grounding.normal=hit.normal;grounding.queryHit=true;grounding.role=type.ToString();gb1Grounded.Add(grounding);var ao=GameObject.CreatePrimitive(PrimitiveType.Quad);Object.DestroyImmediate(ao.GetComponent<Collider>());ao.name="GB1 AO contact";ao.transform.SetParent(root.transform,false);ao.transform.position=hit.point+hit.normal*.012f;ao.transform.rotation=Quaternion.LookRotation(hit.normal);ao.transform.localScale=new Vector3(Mathf.Max(.5f,scale.x*1.2f),Mathf.Max(.4f,scale.z),1);var ar=ao.GetComponent<MeshRenderer>();ar.sharedMaterial=GB1ContactMaterial();ar.shadowCastingMode=ShadowCastingMode.Off;return root;}
        static Material gb1ContactMaterial;static Material GB1ContactMaterial(){if(gb1ContactMaterial==null)gb1ContactMaterial=Save(new Material(Resources.Load<Shader>("Map25D/FootContact")){name="GB1 opaque foot AO contact"},"Contact.mat");return gb1ContactMaterial;}
        static void BuildGB1Nav(Map25DEnvironment env){var vs=new List<Vector3>();var tri=new List<int>();for(int y=0;y<200;y++)for(int x=0;x<200;x++)if(map.CanMove((x+.5f)*40,(y+.5f)*40,0)){int i=vs.Count;foreach(var q in new[]{new Vector2(x*.4f,-y*.4f),new Vector2((x+1)*.4f,-y*.4f),new Vector2(x*.4f,-(y+1)*.4f),new Vector2((x+1)*.4f,-(y+1)*.4f)})vs.Add(new Vector3(q.x,env.HeightSurface.SampleHeight(new Vector3(q.x,0,q.y))-2,q.y));tri.AddRange(new[]{i,i+1,i+2,i+2,i+1,i+3});}var mesh=new Mesh{name="GB1 actual Core walk",indexFormat=IndexFormat.UInt32};mesh.SetVertices(vs);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh=Save(mesh,"NavWalk.asset");var go=new GameObject("NavWalk");go.transform.SetParent(world,false);var surface=go.AddComponent<NavMeshSurface>();var settings=NavMesh.GetSettingsByID(surface.agentTypeID);settings.agentRadius=.1f;settings.agentHeight=1.6f;settings.overrideVoxelSize=true;settings.voxelSize=.04f;settings.minRegionArea=0;var nav=NavMeshBuilder.BuildNavMeshData(settings,new List<NavMeshBuildSource>{new NavMeshBuildSource{shape=NavMeshBuildSourceShape.Mesh,sourceObject=mesh,transform=Matrix4x4.identity,area=0}},new Bounds(new Vector3(40,3,-40),new Vector3(82,16,82)),Vector3.zero,Quaternion.identity);surface.navMeshData=Save(nav,"NavMesh.asset");surface.AddData();int missing=0,extra=0,directMisses=0,verticalMatches=0;float maxHeightDelta=0;var navDiagnostics=new System.Text.StringBuilder("[");for(int y=0;y<200;y++)for(int x=0;x<200;x++){var p=new Vector3((x+.5f)*.4f,0,-(y+.5f)*.4f);p.y=env.HeightSurface.SampleHeight(p)-2;bool core=map.CanMove(p.x*100,-p.z*100,0),n=NavMesh.SamplePosition(p,out var hit,.14f,NavMesh.AllAreas);if(core&&!n)directMisses++;if(!n){for(float dy=-.8f;dy<=.801f;dy+=.08f)if(NavMesh.SamplePosition(p+Vector3.up*dy,out var columnHit,.10f,NavMesh.AllAreas)&&Vector2.Distance(new Vector2(p.x,p.z),new Vector2(columnHit.position.x,columnHit.position.z))<=.105f){n=true;float error=Mathf.Abs(columnHit.position.y-p.y);maxHeightDelta=Mathf.Max(maxHeightDelta,error);if(core){verticalMatches++;if(navDiagnostics.Length>1)navDiagnostics.Append(",");navDiagnostics.Append("{\"x\":"+p.x.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"z\":"+p.z.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"heightDelta\":"+error.ToString(System.Globalization.CultureInfo.InvariantCulture)+"}");}break;}}if(core&&!n)missing++;if(!core&&n)extra++;}navDiagnostics.Append("]");File.WriteAllText(Path.Combine(Output,"gb1-nav-height-diagnostics.json"),navDiagnostics.ToString());File.WriteAllText(Path.Combine(Output,"gb1-nav-contract.json"),"{\"coreWalkNavNo\":"+missing+",\"navWalkCoreNo\":"+extra+",\"direct3dProbeMisses\":"+directMisses+",\"sameXYColumnMatches\":"+verticalMatches+",\"maxNavHeightApproximation\":"+maxHeightDelta.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"horizontalTolerance\":0.105,\"verticalProbeRange\":0.8}");if(missing!=0||extra!=0)throw new Exception("GB1 Core/Nav mismatch "+missing+"/"+extra);}
        static void DiagnosticShot(Camera camera,string path){var rt=new RenderTexture(1920,1080,24,RenderTextureFormat.ARGB32);camera.targetTexture=rt;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(1920,1080,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1920,1080),0,0);texture.Apply();File.WriteAllBytes(path,texture.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=null;rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(texture);}
